func (b *Brewer) Brew(names []string) string {
	available := make([]string, 0, len(names))
	for _, name := range names {
		name = menu.Normalize(name)
		if b.stock.Reserve(name) {
			available = append(available, name)
		}
	}
	return brew(available)
}

